    def bands(n, separator_positions):
        bounds = [-1] + separator_positions + [n]
        return [(bounds[k] + 1, bounds[k + 1]) for k in range(len(bounds) - 1)]

    row_bands = bands(h, [r for r in range(h) if all(v == 8 for v in grid[r])])
    col_bands = bands(w, [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))])
    ph = max(b - a for a, b in row_bands)
    pw = max(b - a for a, b in col_bands)

    valid = [(i, j) for i, (a, b) in enumerate(row_bands)
             for j, (c, d) in enumerate(col_bands)
             if b - a == ph and d - c == pw]

    seeds = {2: set(), 3: set()}
    for i, j in valid:
        y0, y1 = row_bands[i]
        x0, x1 = col_bands[j]
        for y in range(y0, y1):
            for x in range(x0, x1):
                if grid[y][x] in seeds:
                    seeds[grid[y][x]].add((i, j))

    painted = {2: set(), 3: set()}
    for color, points in seeds.items():
        pts = list(points)
        for k, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[k + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[color].add((r1, c))
                if c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[color].add((r, c1))

    out = [row[:] for row in grid]
    for i, j in valid:
        color = 6 if (i, j) in painted[2] and (i, j) in painted[3] else \
                2 if (i, j) in painted[2] else 3 if (i, j) in painted[3] else 0
        if color:
            y0, y1 = row_bands[i]
            x0, x1 = col_bands[j]
            for y in range(y0, y1):
                for x in range(x0, x1):
                    out[y][x] = color
    return out
